window.SHL_FILES = Object.assign(window.SHL_FILES || {}, {"leagues/vacuum/bots/battery.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles atgoal distto angleto stopgoto timeleft dockx docky\n# ============================================================\n#  BATTERY RUNNER  -  for the U19 league.\n#\n#  In U19 the robot runs on a battery:\n#     battery        100 -> 0   (100% is about 60 s of full speed)\n#     dockx, docky   the charging station, in cm - it has a FIXED\n#                    home by the wall, the same in every match\n#\n#  Park ON the pad and it refills at +25% per second.\n#  An EMPTY battery STOPS the robot dead, right where it\n#  stands, for the rest of the match - so the real skill\n#  is leaving for the dock in time, every time.\n#\n#  The 10 s \"stuck\" watchdog is paused while you charge, but it\n#  is back the moment you hit 100% - so do not camp on the pad.\n#\n#  HOW MUCH CHARGE DO I NEED TO GET HOME?\n#  At full speed the robot burns about 1.7% per second and covers\n#  about 60 cm in that second - but the RUG halves your speed and\n#  the trip is never a straight line, so budget generously:\n#         distto(dockx, docky) / 25   percent.\n#  Plus a FAT margin, because goto() drives a STRAIGHT line and\n#  the real trip never is: round the sofa, wait for the dog, back\n#  out of a corner. Dying at 0% is now FINAL - once the battery is\n#  empty the robot stands there for the rest of the match - so\n#  when in doubt, leave for the dock EARLY.\n#\n#  THE STATE MACHINE\n#     state 0   cleaning\n#     state 1   driving home\n#     state 2   sitting on the pad, drinking\n#     state 3   backing out of whatever we hit\n#     state 4   sidestepping ALONG it before trying again\n#  Writing it as states is what makes it reliable: whatever\n#  happens, the robot always knows what it was in the middle of.\n#  The escape side (flip) is read off the SENSORS at each bump -\n#  we back out toward whichever side is open. Bashing the same\n#  corner from the same angle over and over is how batteries die.\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\nfront = 200; frontleft = 200; frontright = 200\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0; movetime = 0; atgoal = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nbattery = 100; dockx = -1; docky = -1\ndust = 0; dustmax = 0; dustfull = 0; dumpx = -1; dumpy = -1\nhome = 0; needed = 0; flip = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\n\n# ---------- how far is home, and how low is too low? ----------\nhome = distto(dockx, docky)\nneeded = home / 25 + 25\n\n\n# ---------- state 3: back out of whatever we hit ----------\nif state == 3:\n    if timer > 0:\n        timer -= 1\n        if flip < 1:             # the side picked at the moment of the bump\n            wheelleft = -22\n            wheelright = -8\n        else:\n            wheelleft = -8\n            wheelright = -22\n    else:\n        state = 4                # clear of it -> now slide ALONG it\n        timer = 12\n\n\n# ---------- state 4: sidestep along the obstacle, then retry ----------\nelif state == 4:\n    if bumper == 1:              # hit something ELSE mid-sidestep? back out\n        if frontleft > frontright:\n            flip = 0             # again toward whichever side is open NOW\n        else:\n            flip = 1\n        state = 3\n        timer = 10\n        wheelleft = -20\n        wheelright = -8\n    elif timer > 0:\n        timer -= 1\n        if flip < 1:\n            wheelleft = 8        # a forward arc across the obstacle's face,\n            wheelright = 24      # not into it\n        else:\n            wheelleft = 24\n            wheelright = 8\n    else:\n        state = 1                # try the trip home again from HERE\n        timer = 200              # fresh 20-second deadline\n        goto(dockx, docky)\n\n\n# ---------- state 2: on the pad, drinking ----------\nelif state == 2:\n    wheelleft = 0                # do NOT roll off the pad\n    wheelright = 0\n    if battery > 95:\n        state = 0                # full -> back to work\n\n\n# ---------- state 1: driving home ----------\nelif state == 1:\n    timer -= 1\n    if bumper == 1 or timer <= 0:\n        # hit something - or the trip went STALE (20 s without arriving).\n        # Either way: stop, back out toward the open side, try fresh.\n        stopgoto()\n        if frontleft > frontright:\n            flip = 0             # more room to the LEFT -> escape that way\n        else:\n            flip = 1             # more room to the RIGHT\n        state = 3\n        timer = 10\n        wheelleft = -20\n        wheelright = -8\n    elif home < 25:              # close enough: stop and let it charge\n        stopgoto()\n        state = 2\n        wheelleft = 0\n        wheelright = 0\n    # else: goto is steering, leave the wheels alone\n\n\n# ---------- state 0: cleaning ----------\nelse:\n    # time to head home? Two triggers: the sensible one, and the emergency one.\n    if dockx > 0 and battery < needed:\n        state = 1\n        timer = 200              # a trip gets 20 seconds, then we rethink -\n        goto(dockx, docky)       # long enough to cross the slow rug honestly\n    elif dockx > 0 and battery < 20:\n        state = 1\n        timer = 200\n        goto(dockx, docky)\n\n    elif front < 25 or bumper == 1:      # something right ahead -> turn away\n        wheelleft = 25\n        wheelright = -25\n    elif frontleft < frontright:         # more room on the right\n        wheelleft = 25\n        wheelright = 12\n    elif frontright < frontleft:         # more room on the left\n        wheelleft = 12\n        wheelright = 25\n    else:\n        wheelleft = 25                   # clear -> full speed, clean!\n        wheelright = 25\n", "leagues/vacuum/bots/colorsensor.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles\n# ============================================================\n#  EXAMPLE: reading the COLOUR SENSOR by name\n#  Load this with the Load .py button and press Start.\n#\n#  >>>>>>  timer = 10  MEANS  1 SECOND  <<<<<<\n#          your code runs 10 times every second\n#\n#  The colour sensor sits at the robot's NOSE and reads the floor\n#  just AHEAD of it:\n#     white   = floor ahead not cleaned yet  -> the points are there\n#     red     = floor ahead was cleaned by the red robot\n#     blue    = floor ahead was cleaned by the blue robot\n#     green   = the BIG rug is ahead   (half speed, no points)\n#     purple  = the SMALL rug is ahead (no points)\n#     black   = a wall or furniture is right ahead\n#\n#  This file shows the SYNTAX. Beating the base code is your job:\n#  try reacting to red / blue / white in smarter ways.\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\n# Do NOT write your own code inside this block.\nfront = 200; frontleft = 200; frontright = 200\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\nwheelleft = 25\nwheelright = 25\n\nif timer > 0:                # still finishing the last move\n    timer -= 1\n    wheelleft = 18\n    wheelright = -18         # turn in place\n\nelif front < 75 or frontleft < 45 or frontright < 45:\n    timer = 3                # wall or furniture ahead -> back off, then turn\n    wheelleft = -10\n    wheelright = -10\n\n# purple / orange / cyan rugs mark the DOORWAYS: never turn back at one,\n# or you will never get into the room. Drive over them.\n\nelif color == green:         # the big green rug is ahead -> turn away from it\n    timer = 4\n    wheelleft = -10\n    wheelright = -10\n\nelif color == white:         # clean floor ahead -> points, full speed\n    wheelleft = 25\n    wheelright = 25\n\nelse:                        # red or blue ahead: already cleaned, keep moving\n    wheelleft = 25\n    wheelright = 25\n", "leagues/vacuum/bots/easymoves.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles\n# ============================================================\n#  EXAMPLE — EASY MOVES + the colour sensor\n#  One call = one whole move; the number is real SECONDS.\n#  Uses: color, bumper, front, backward(), turnright()\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\nfront = 200; frontleft = 200; frontright = 200\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0; movetime = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\nwheelleft = 25                  # default: straight ahead, full speed\nwheelright = 25\n\nif color == green:              # big rug ahead - it slows us down\n    backward(2)                 # (purple / orange / cyan rugs mark the doors: drive over them)\n\nelif bumper == 1:               # hit something - back away for a second\n    backward(1)\n\nelif front < 50:                # wall ahead - spin right for 0.6 s\n    turnright(0.6)\n", "leagues/vacuum/bots/goto.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles atgoal distto angleto stopgoto timeleft\n# ============================================================\n#  GOTO PATROL  -  the position sensor (GPS) in action.\n#\n#  The map is centimetres: the BOTTOM-LEFT corner is (0,0),\n#  x grows to the right, y grows UP. On the standard map the\n#  far corner is (1000,1000) and the centre is (500,500).\n#\n#  goto(x, y)  drives to that point on the STRAIGHT line and\n#  stops there by itself. atgoal turns 1 when it arrives.\n#  goto does NOT dodge obstacles - the bumper code below\n#  backs off and re-aims whenever we hit something.\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\nfront = 200; frontleft = 200; frontright = 200\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0; movetime = 0; atgoal = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\n\n# ---------- patrol the four corners, forever ----------\n# state remembers which corner we are heading to (1..4).\n\nif state == 0:                   # first step of the match -> aim corner 1\n    state = 1\n    goto(150, 150)\n\nelif atgoal == 1:                # arrived -> aim the NEXT corner\n    state = state + 1\n    if state == 2:\n        goto(150, 850)           # top-left area\n    elif state == 3:\n        goto(850, 850)           # top-right area\n    elif state == 4:\n        goto(850, 150)           # bottom-right area\n    else:\n        state = 1\n        goto(150, 150)           # back to the start corner\n\n# ---------- safety: goto drives a straight line, it does not dodge ----------\nif bumper == 1:                  # hit furniture / wall / cat / dog / rival\n    stopgoto()                   # take the wheels back...\n    backward(1)                  # ...back off for a second\nelif timer > 0:                  # (nothing else to do - goto is steering)\n    timer -= 1\n\n# after the back-off ends, aim the same corner again\nif bumper == 0 and atgoal == 0 and state > 0:\n    if distto(150, 150) > 0 and state == 1:\n        goto(150, 150)\n    elif state == 2:\n        goto(150, 850)\n    elif state == 3:\n        goto(850, 850)\n    elif state == 4:\n        goto(850, 150)\n", "leagues/vacuum/bots/hunter.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles\n# ============================================================\n#  EXAMPLE — TILE HUNTER\n#  Sweeps fast, avoids the rugs, and when the round is almost over\n#  it plays even more aggressively to steal tiles back.\n#  Uses: all 3 front sensors, color, bumper, timeleft, timer + state\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\nfront = 200; frontleft = 200; frontright = 200\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0; movetime = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\nwheelleft = 25                   # default: sweep at full speed\nwheelright = 25\n\nif timer > 0:                    # keep the started move going\n    timer -= 1\n    if state == 2:               # reversing in a curve\n        wheelleft = -25\n        wheelright = -10\n    elif state == 1:             # turning right\n        wheelleft = 18\n        wheelright = -18\n    else:                        # turning left\n        wheelleft = -18\n        wheelright = 18\n\nelif bumper == 1:                # touched something -> curve back 0.5 s\n    state = 2\n    timer = 5\n    wheelleft = -25\n    wheelright = -10\n\nelif front < 65:                 # wall ahead -> back off + turn right\n    state = 1\n    timer = 4\n    wheelleft = -12\n    wheelright = -12\n\nelif frontleft < 40:             # blocked on the left -> turn right\n    state = 1\n    timer = 3\n    wheelleft = -10\n    wheelright = -10\n\nelif frontright < 40:            # blocked on the right -> turn LEFT\n    state = -1\n    timer = 3\n    wheelleft = -10\n    wheelright = -10\n\nelif color == green:                         # the big rug slows us - get out (marker rugs at the doors: drive over)\n    state = 2\n    timer = 6\n    wheelleft = -25\n    wheelright = -10\n\nelif timeleft < 30 and color == white:       # last 30 s: grab clean floor hard\n    wheelleft = 25\n    wheelright = 25\n", "leagues/vacuum/bots/wallfollow.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles\n# ============================================================\n#  EXAMPLE — WALL FOLLOWING with the distance sensors\n#  Keeps the wall on the RIGHT side and sweeps the edge of the room.\n#  Uses: front, right, bumper, timer\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\nfront = 200; frontleft = 200; frontright = 200\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0; movetime = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\nwheelleft = 25                  # default: straight ahead\nwheelright = 25\n\nif timer > 0:                   # finishing a turn away from a bump\n    timer -= 1\n    wheelleft = -18\n    wheelright = 18\n\nelif bumper == 1:               # touched something -> spin left for 0.4 s\n    timer = 4\n    wheelleft = -18\n    wheelright = 18\n\nelif front < 60:                # wall straight ahead -> turn left now\n    wheelleft = -18\n    wheelright = 18\n\nelif right > 70:                # lost the wall -> curve right to find it\n    wheelleft = 25\n    wheelright = 13\n\nelif right < 35:                # hugging too close -> curve away a little\n    wheelleft = 13\n    wheelright = 25\n", "leagues/vacuum/fs/program.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles atgoal distto angleto stopgoto timeleft\n# ============================================================\n#  YOUR ROBOT BRAIN  -  your code runs 10 times every second.\n#  Read the sensors, then set the two wheels.\n#  🧠 مغز ربات تو — این فایل ۱۰ بار در هر ثانیه اجرا می‌شود:\n#  اول سنسورها را می‌خوانی، بعد دو چرخ را تنظیم می‌کنی. همین!\n#\n#  >>>>>>  timer = 10  MEANS  1 SECOND  <<<<<<\n#          timer = 5 -> half a second      timer = 20 -> 2 seconds\n#          NOT milliseconds!  timer = 500 would reverse for 50 seconds!\n#          EASIEST WAY:  timer = seconds(10)  ->  exactly 10 seconds\n#  ⏱ یعنی timer = 10 می‌شود «۱ ثانیه» (نه میلی‌ثانیه!).\n#     timer = 5 نیم ثانیه است و timer = 500 یعنی ۵۰ ثانیه دنده‌عقب!\n#     راحت‌ترین راه: timer = seconds(10) یعنی دقیقاً ۱۰ ثانیه.\n#\n#  All the numbers are written right where they are used -\n#  change any number and the robot changes.\n#  🔢 همه‌ی عددها همان‌جایی نوشته شده‌اند که استفاده می‌شوند —\n#     هر عددی را عوض کنی، رفتار ربات همان لحظه عوض می‌شود.\n#\n#  THE FS ROBOT HAS SIX THINGS IT CAN FEEL - and no more.\n#  Three eyes forward, the bumper ring, and the colour sensor.\n#  (Side and rear eyes, the compass and the GPS are U14's.)\n#  🤖 ربات FS فقط شش حس دارد، نه بیشتر: سه چشم رو به جلو،\n#     حلقه‌ی ضربه (سپر)، و سنسور رنگ. چشم بغل و عقب، قطب‌نما\n#     و GPS مال رده‌ی U14 به بالاست.\n#\n#  DISTANCE SENSORS  (distance in cm, smaller = closer, max = 200)\n#     frontleft   front   frontright\n#  📏 سنسورهای فاصله (سانتی‌متر): عدد کوچک‌تر یعنی نزدیک‌تر؛ بیشینه ۲۰۰.\n#     frontleft چپِ جلو · front روبه‌رو · frontright راستِ جلو\n#\n#  BUMPER  (the ring around the robot - you are told WHICH HALF)\n#     bumperfront == 1   I ran into something with my front\n#     bumperback  == 1   something touched my back\n#     bumper      == 1   either of them - anything at all is touching me\n#  🛟 سپر (حلقه‌ی دور ربات — می‌گوید کدام نیمه خورده):\n#     bumperfront یعنی از جلو خوردم · bumperback یعنی از پشت خوردم\n#     bumper یعنی هر کدام — بالاخره چیزی به من چسبیده!\n#\n#  COLOUR SENSOR  (at the robot's NOSE - it reads the floor just AHEAD)\n#     color   ==  white    floor ahead not cleaned yet  -> go get it!\n#     color   ==  red      floor ahead was cleaned by the red robot\n#     color   ==  blue     floor ahead was cleaned by the blue robot\n#     color   ==  green    the BIG rug is ahead   (half speed, no points)\n#     color   ==  purple   the SMALL rug is ahead (no points)\n#     color   ==  black    a wall or furniture is right ahead\n#  🎨 سنسور رنگ (نوک ربات — رنگ کفِ جلوی ربات را می‌گوید):\n#     white کف تمیزنشده — برو بگیرش! · red مال ربات قرمز · blue مال آبی\n#     green فرش بزرگ (نصف سرعت، بی‌امتیاز) · purple فرش کوچک (بی‌امتیاز)\n#     black دیوار یا مبل درست جلوی توست\n#  Turn on \"Sensors\" in the top-left menu to SEE every sensor, the\n#  colour name and the wheel speeds live while your robot drives!\n#  💡 از منوی بالا-چپ «Sensors» را روشن کن تا همه‌ی سنسورها، رنگ و\n#     سرعت چرخ‌ها را همان لحظه که ربات می‌راند ببینی — و ببینی الان\n#     کدام خط کدت دارد فرمان می‌دهد!\n#\n#  TIMER  (your own countdown, keeps its value between steps)\n#     Your code runs 10 times per second, so:\n#        timer = 10  ->  1 second      timer = 5  ->  half a second\n#     IMPORTANT: timer does NOTHING by itself! Setting it only works\n#     together with the \"if timer > 0:\" block at the top of the logic -\n#     THAT block is what keeps the move going, step after step.\n#     In this file also set `state` so the block knows WHICH move to\n#     continue:  state = 2 reverse   state = 1 turn right   -1 turn left\n#  ⏳ تایمر (شمارش معکوس خودت — بین اجراها عددش می‌ماند):\n#     مهم: timer به‌تنهایی هیچ کاری نمی‌کند! فقط همراهِ بلوک\n#     «if timer > 0:» بالای منطق کار می‌کند — همان بلوک است که حرکت را\n#     قدم‌به‌قدم ادامه می‌دهد. state هم می‌گوید «کدام» حرکت ادامه یابد:\n#     state = 2 دنده‌عقب · state = 1 چرخش به راست · state = -1 به چپ\n#\n#  EASY MOVES  (one call = the whole move, NO timer or state needed!)\n#     backward(5)   drive backward for exactly 5 seconds\n#     forward(2)    drive forward for 2 seconds\n#     turnleft(1)   turnright(1)   spin for 1 second\n#     stop(2)       stand still for 2 seconds\n#     Example:      elif bumper == 1:\n#                       backward(1)\n#     While a move is running, new move calls are ignored until it ends.\n#  🎮 حرکت‌های آسان (یک دستور = کل حرکت؛ بدون timer و state):\n#     backward(5) پنج ثانیه عقب · forward(2) دو ثانیه جلو\n#     turnleft(1) و turnright(1) یک ثانیه چرخش · stop(2) دو ثانیه ایست\n#     تا حرکتی تمام نشده، دستور حرکتِ تازه نادیده گرفته می‌شود.\n#\n#  MOVETIME  (hold MY wheels — variable style, countdown is automatic)\n#     Set the wheels yourself, then say how long to KEEP them:\n#        elif color == green:\n#            wheelleft = -25\n#            wheelright = -25\n#            movetime = seconds(10)   # keep reversing for exactly 10 s\n#     The minus-minus happens by itself - no \"if timer > 0\" block needed.\n#     movetime counts down in the panel; 0 means the hold is over.\n#  🕐 با movetime چرخ‌ها را خودت تنظیم می‌کنی و می‌گویی چقدر نگهشان\n#     دارد — شمارش خودکار است و به بلوک «if timer > 0» نیازی نیست.\n#\n#  ROOMS  (only on maps that have them, like the Rooms house)\n#     room == 0   the living area / hall     room == 1   the KITCHEN\n#     room == 2   BEDROOM 1                  room == 3   BEDROOM 2\n#     clean1 / clean2 / clean3   how much of that room wears MY\n#     colour, 0..100 percent - so I can tell a finished room from\n#     one still waiting:  if clean2 > 80: go somewhere else!\n#     A marker rug sits at every door: purple = bedroom 1,\n#     green = the kitchen, purple on the south side = bedroom 2.\n#  🚪 اتاق‌ها (فقط روی نقشه‌هایی که اتاق دارند، مثل خانه‌ی Rooms):\n#     room شماره‌ی اتاقی است که الان در آنم؛ clean1 تا clean3 می‌گوید\n#     چند درصد از آن اتاق رنگِ من شده — اتاق تمام‌شده را ول کن برو بعدی!\n#     دم هر در یک فرش نشانه هست: بنفش = اتاق‌خواب ۱، سبز = آشپزخانه.\n#\n#  INFO\n#     x, y  position (cm)   heading  facing (0..360 deg)\n#     mytiles / rivaltiles  tiles owned      timeleft  seconds left\n#  ℹ️ اطلاعات: x و y جای من (سانتی‌متر) · heading جهت (۰ تا ۳۶۰ درجه)\n#     mytiles کاشی‌های من · rivaltiles مالِ حریف · timeleft ثانیه‌های مانده\n#\n#  POSITION (GPS)  -  the BOTTOM-LEFT corner is (0,0), x grows right, y grows UP\n#     On the standard map the far corner is (1000,1000), the centre (500,500).\n#        goto(500, 500)   drive there on the straight line, hands-free;\n#                         the robot turns, drives, and stops by itself\n#        atgoal == 1      the goto has arrived (0 while still driving)\n#        distto(x, y)     distance to a point in cm\n#        angleto(x, y)    compass direction to a point (compare with heading)\n#        stopgoto()       cancel the goto and take the wheels back\n#     goto does NOT dodge furniture, walls, the cat or the dog -\n#     watch bumper and the sensors while it drives!\n#     Example:   if timeleft < 20:\n#                    goto(500, 500)      # go camp the centre at the end\n#  📍 جی‌پی‌اس: گوشه‌ی پایین-چپ (0,0) است. goto(500,500) یعنی خودش\n#     تا آن نقطه براند و بایستد؛ atgoal که ۱ شد یعنی رسید.\n#     حواست باشد: goto از روی مبل و دیوار و گربه رد نمی‌شود —\n#     موقع راندنش، سپر و سنسورها را بپا!\n#\n#  BATTERY + CHARGING STATION  -  the U19 league only\n#     battery          0..100, how much charge is left\n#                      100% = about 60 s of full-throttle driving\n#     dockx, docky     where the charging station is, in cm (same grid as x,y)\n#                      a FIXED home by the east shelf - the same every match\n#                      both are -1 in FS and U14 (there is no station)\n#     Park ON the pad to refill: +25% per second. An EMPTY battery STOPS the\n#     robot dead where it stands - it will not move again, so leave enough\n#     charge to get back!   Rule of thumb: keep more than\n#         distto(dockx, docky) / 30   percent in the tank.\n#     Example:   if battery < 30:\n#                    goto(dockx, docky)  # go charge, then carry on\n#     The 10s \"stuck\" watchdog is paused while you are charging, but it\n#     comes back the moment you are full - do NOT camp on the pad.\n#  🔋 باتری و ایستگاه شارژ (فقط رده‌ی U19): باتری ۱۰۰٪ یعنی حدود\n#     ۶۰ ثانیه راندن با تمام سرعت. روی پد پارک کن تا ۲۵٪ در ثانیه پر شود.\n#     باتریِ صفر یعنی ربات همان‌جا برای همیشه خاموش می‌ماند — پس همیشه\n#     به‌اندازه‌ی راهِ برگشت شارژ نگه دار: distto(dockx, docky) / 30 درصد.\n#\n#  ASSISTIVE TECHNOLOGY league  -  you are GUIDING a person\n#     backleft, backright  the person walks BEHIND you - this is how you\n#                          notice when they stop or fall behind\n#     personback           distance to them in cm (60-70 = comfortable)\n#     personwait == 1      they lost you and stopped to wait\n#     goalx, goaly         where they want to go   (-1 in U19)\n#     goalname             WHICH room: compare with kitchen / door / sofa /\n#                          bedroom / window / table\n#     roomx(kitchen)       ask the house for a room's address (U19)\n#     goalsleft            destinations still to deliver\n#     Fast is NOT the goal: +30 arriving with them, +20 for a chore\n#     done alone, -6 if they hit furniture, -100 if they FALL, and\n#     violent swerves cost too.\n#  🦯 لیگ فناوری کمکی: تو راهنمای یک آدم هستی که پشت سرت راه می‌رود.\n#     personback فاصله‌اش تا توست (۶۰ تا ۷۰ خوب است) و سرعتِ زیاد\n#     اصلاً هدف نیست — اگر بیفتد ۱۰۰ امتیاز از دست می‌دهی!\n#\n#  SUMO league  -  the knockout bout (that league ships its own program)\n#     arenax, arenay, arenar  the platform: centre and radius (cm)\n#     edge                    my distance to the drop, in cm\n#     rivalx, rivaly          where the rival is\n#     cliff1..cliffN == 1     that edge sensor sees the DROP\n#     Shove the rival off the platform - first to 3 knockouts wins.\n#  🤼 لیگ سومو: حریف را از سکو بینداز پایین — edge فاصله‌ی من تا لبه\n#     است و cliff یعنی آن سنسور لبه، پرتگاه را می‌بیند.\n#\n#  WHEELS  (set these every step, from -25 to 25)\n#      25,  25  = forward, full speed      -25, -25 = backward\n#      25, -25  = turn right in place      -25,  25 = turn left in place\n#      12,  12  = forward at half speed\n#  🛞 چرخ‌ها (هر قدم مقدار بده؛ از -۲۵ تا ۲۵):\n#     «۲۵ و ۲۵» جلو با تمام سرعت · «-۲۵ و -۲۵» عقب\n#     «۲۵ و -۲۵» چرخش درجا به راست · «-۲۵ و ۲۵» به چپ · «۱۲ و ۱۲» نصف سرعت\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\n# Do NOT write your own code inside this block.\n# بازی این بلوک را کامل رد می‌کند! فقط برای این است که ویرایشگر کد\n# اسم سنسورها را بشناسد و زیرشان خط قرمز نکشد. کد خودت را اینجا ننویس.\nfront = 200; frontleft = 200; frontright = 200\nbumperfront = 0; bumperback = 0\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0; movetime = 0; atgoal = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nbattery = 100; dockx = -1; docky = -1\npersonback = 60; personwait = 0; goalx = -1; goaly = -1; goalname = 0; goalsleft = 0\nkitchen = 1; door = 2; sofa = 3; bedroom = 4; window = 5; table = 6\nzonex = -1; zoney = -1; zoner = -1; inzone = 0; rivalinzone = 0; rivalx = -1; rivaly = -1\nroom = 0; clean1 = 0; clean2 = 0; clean3 = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\n\n# ---------- HOW THIS WORKS ----------\n# This file runs 10 times every second, from top to bottom.\n# Your code cannot \"wait\", so a move that should last a while is started\n# by putting a number in `timer`, and `state` remembers WHICH move it is:\n#     state = 1  -> turning right      state = -1 -> turning left\n#     state = 2  -> reversing\n# Every step the first block counts the timer down and keeps that move going.\n#\n# 🧭 این‌جوری کار می‌کند: کدت نمی‌تواند «صبر» کند؛ حرکتی که باید طول\n# بکشد را با گذاشتن یک عدد در timer شروع می‌کنی و state یادش می‌ماند\n# «کدام» حرکت بود. بلوک اول در هر قدم تایمر را کم می‌کند و همان حرکت\n# را ادامه می‌دهد.\n#\n# HOW LONG IS A TURN?  timer counts steps, 10 steps = 1 second:\n#     timer = 3   ->  0.3 s of turning  =  about  50 degrees\n#     timer = 5   ->  0.5 s of turning  =  about  80 degrees\n#     timer = 10  ->  1.0 s of turning  =  about 165 degrees\n# Want the robot to turn further? Just use a BIGGER number in timer.\n# 🔄 چقدر بچرخم؟ timer قدم می‌شمارد و ۱۰ قدم = ۱ ثانیه:\n#     timer = 3 حدود ۵۰ درجه · timer = 5 حدود ۸۰ درجه · timer = 10 حدود ۱۶۵ درجه\n#     چرخش بیشتر می‌خواهی؟ عدد بزرگ‌تری در timer بگذار.\n#\n# Add your own elif branches below - the first one that is true wins.\n# ✍️ شاخه‌های elif خودت را پایین اضافه کن — اولین شرطِ درست برنده است.\n\n\n# ---------- THE ROBOT LOGIC ----------\n\nwheelleft = 25                   # by default: drive straight ahead, full speed\nwheelright = 25                  # پیش‌فرض: مستقیم جلو با تمام سرعت\n\n# ۱) آیا هنوز مشغول حرکت قبلی‌ام؟ تا timer صفر نشده همان را ادامه بده.\nif timer > 0:                    # 1) am I still busy with the last move?\n    timer -= 1\n    if state == 2:               #    reversing in a curve (one wheel slower,\n        wheelleft = -25          #    so we also rotate away and do not drive\n        wheelright = -8          #    straight back into the same spot)\n                                 #    دنده‌عقبِ کج: یک چرخ کندتر، تا هم دور\n                                 #    شویم هم دوباره به همان‌جا برنگردیم\n    elif state == 1:             #    turning right · چرخش به راست\n        wheelleft = 18\n        wheelright = -18\n    else:                        #    turning left · چرخش به چپ\n        wheelleft = -18\n        wheelright = 18\n\n# ۲) چیزی به پشتم خورده! دنده‌عقب فقط محکم‌تر فشارش می‌دهد —\n#    راه نجات، جلو رفتن است. برای همین حلقه‌ی سپر دو نیمه دارد.\nelif bumperback == 1:            # 2) something is touching MY BACK. Reversing\n    state = 1                    #    now would only press it harder, so the\n    timer = 6                    #    way out is FORWARD - and then turn right.\n    wheelleft = 25               #    This is why the ring has two halves.\n    wheelright = 25\n\n# ۳) با جلو به چیزی کوبیدم — عقب بکش و بعد ۰٫۶ ثانیه (حدود ۱۰۰ درجه)\n#    بچرخ تا تلاش بعدی از جای واقعاً تازه‌ای شروع شود.\nelif bumperfront == 1:           # 3) I RAN INTO something with my front\n    state = 1                    #    -> back off, then keep turning right for\n    timer = 6                    #    0.6 s (about 100 degrees), so the next\n    wheelleft = -25              #    try starts somewhere genuinely new\n    wheelright = -25\n\n# ۴) دیوار نزدیک‌تر از ۷۵ سانتی‌متر روبه‌روست — عقب بکش، بعد راست بچرخ.\n#    timer = 3 یعنی ۰٫۳ ثانیه چرخش (حدود ۵۰ درجه)؛ عدد بزرگ‌تر = چرخش بیشتر!\nelif front < 75:                 # 4) wall closer than 75 cm ahead\n    state = 1                    #    -> back off, then turn right\n    timer = 3                    #    timer = 3 -> turn 0.3 s (about 50 degrees)\n    wheelleft = -10              #       use a bigger number to turn further!\n    wheelright = -10\n\n# ۵) چیزی نزدیک‌تر از ۴۵ سانتی‌متر سمتِ چپِ جلوست — عقب بکش، راست بچرخ.\nelif frontleft < 45:             # 5) something closer than 45 cm on my LEFT\n    state = 1                    #    -> back off, then turn right\n    timer = 3\n    wheelleft = -10\n    wheelright = -10\n\n# ۶) چیزی سمتِ راستِ جلوست. 🧪 امتحان کن: state را -1 کن (چرخش به چپ)\n#    و ببین ربات چطور گیج می‌زند و گیر می‌کند — همیشه یک‌طرفه چرخیدن پایدارتر است!\nelif frontright < 45:            # 6) something closer than 45 cm on my RIGHT\n    state = 1                    #    TRY THIS: change to -1 (turn left) and watch\n    timer = 3                    #    the robot start to wobble and get stuck.\n    wheelleft = -10              #    Turning the same way every time is steadier!\n    wheelright = -10\n\n# 7) فرش‌ها: به‌صورت پیش‌فرض ربات از روی هر فرشی رد می‌شود و به رنگ کاری ندارد.\n#    اگر خواستی واکنش نشان بدهد، این چند خط را از کامنت دربیاور (مثلاً برای فرش بنفش):\n# elif color == purple:            # 7) the small PURPLE rug is right ahead\n#     state = 2                    #    -> reverse away from it for half a second\n#     timer = 5\n#     wheelleft = -25\n#     wheelright = -25\n\n# YOUR TURN: the big GREEN rug slows you down and gives no points,\n# but this code does nothing about it! Add your own elif here, e.g.:\n#     elif color == green:\n#         state = 2            # 2 = reverse (the timer block continues it!)\n#         timer = 10           # for 1 second\n#         wheelleft = -25\n#         wheelright = -25\n# Without state and timer the move stops the moment green disappears.\n# ✍️ نوبت توست: فرش سبزِ بزرگ سرعتت را نصف می‌کند و امتیازی هم ندارد،\n#    ولی این کد هیچ کاری برایش نمی‌کند! elif خودت را همین‌جا اضافه کن\n#    (نمونه‌اش بالاست). بدون state و timer، حرکت همان لحظه‌ای که سبز\n#    از جلوی سنسور برود قطع می‌شود.\n\nelse:                            # 8) nothing in the way -> full speed ahead\n    wheelleft = 25               #    راه باز است — با تمام سرعت تمیز کن!\n    wheelright = 25\n", "leagues/vacuum/u14/program.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles atgoal distto angleto stopgoto timeleft\n# ============================================================\n#  YOUR ROBOT BRAIN  -  your code runs 10 times every second.\n#  Read the sensors, then set the two wheels.\n#  🧠 مغز ربات تو — این فایل ۱۰ بار در هر ثانیه اجرا می‌شود:\n#  اول سنسورها را می‌خوانی، بعد دو چرخ را تنظیم می‌کنی. همین!\n#\n#  >>>>>>  timer = 10  MEANS  1 SECOND  <<<<<<\n#          timer = 5 -> half a second      timer = 20 -> 2 seconds\n#          NOT milliseconds!  timer = 500 would reverse for 50 seconds!\n#          EASIEST WAY:  timer = seconds(10)  ->  exactly 10 seconds\n#  ⏱ یعنی timer = 10 می‌شود «۱ ثانیه» (نه میلی‌ثانیه!).\n#     timer = 5 نیم ثانیه است و timer = 500 یعنی ۵۰ ثانیه دنده‌عقب!\n#     راحت‌ترین راه: timer = seconds(10) یعنی دقیقاً ۱۰ ثانیه.\n#\n#  All the numbers are written right where they are used -\n#  change any number and the robot changes.\n#  🔢 همه‌ی عددها همان‌جایی نوشته شده‌اند که استفاده می‌شوند —\n#     هر عددی را عوض کنی، رفتار ربات همان لحظه عوض می‌شود.\n#\n#  DISTANCE SENSORS  (distance in cm, smaller = closer, max = 200)\n#     frontleft   front   frontright\n#     left                right\n#     backleft            backright\n#  📏 سنسورهای فاصله (سانتی‌متر): عدد کوچک‌تر یعنی نزدیک‌تر؛ بیشینه ۲۰۰.\n#     سه چشم جلو، دو چشم بغل، دو چشم عقب — نقشه‌شان همین بالاست.\n#\n#  BUMPER  (the ring around the robot)\n#     bumper == 1   I am touching a wall, furniture, the cat, the dog or the rival\n#     bumper == 0   nothing is touching me\n#  🛟 سپر (حلقه‌ی دور ربات): bumper == 1 یعنی به دیوار، مبل، گربه،\n#     سگ یا حریف چسبیده‌ام؛ صفر یعنی آزادم.\n#\n#  COLOUR SENSOR  (at the robot's NOSE - it reads the floor just AHEAD)\n#     color   ==  white    floor ahead not cleaned yet  -> go get it!\n#     color   ==  red      floor ahead was cleaned by the red robot\n#     color   ==  blue     floor ahead was cleaned by the blue robot\n#     color   ==  green    the BIG rug is ahead   (half speed, no points)\n#     color   ==  purple   the SMALL rug is ahead (no points)\n#     color   ==  black    a wall or furniture is right ahead\n#  🎨 سنسور رنگ (نوک ربات — رنگ کفِ جلو را می‌گوید):\n#     white کف تمیزنشده — برو بگیرش! · red مال قرمز · blue مال آبی\n#     green فرش بزرگ (نصف سرعت، بی‌امتیاز) · purple فرش کوچک (بی‌امتیاز)\n#     black دیوار یا مبل درست جلوی توست\n#  Turn on \"Sensors\" in the top-left menu to SEE every sensor, the\n#  colour name and the wheel speeds live while your robot drives!\n#  💡 «Sensors» را از منوی بالا-چپ روشن کن تا سنسورها، رنگ و سرعت\n#     چرخ‌ها را زنده ببینی — و این‌که الان کدام خط کدت فرمان می‌دهد.\n#\n#  TIMER  (your own countdown, keeps its value between steps)\n#     Your code runs 10 times per second, so:\n#        timer = 10  ->  1 second      timer = 5  ->  half a second\n#     IMPORTANT: timer does NOTHING by itself! Setting it only works\n#     together with the \"if timer > 0:\" block at the top of the logic -\n#     THAT block is what keeps the move going, step after step.\n#     In this file also set `state` so the block knows WHICH move to\n#     continue:  state = 2 reverse   state = 1 turn right   -1 turn left\n#  ⏳ تایمر: به‌تنهایی هیچ کاری نمی‌کند! فقط همراهِ بلوک «if timer > 0:»\n#     بالای منطق کار می‌کند — همان بلوک حرکت را قدم‌به‌قدم ادامه می‌دهد.\n#     state هم می‌گوید «کدام» حرکت: 2 دنده‌عقب · 1 راست · -1 چپ\n#\n#  EASY MOVES  (one call = the whole move, NO timer or state needed!)\n#     backward(5)   drive backward for exactly 5 seconds\n#     forward(2)    drive forward for 2 seconds\n#     turnleft(1)   turnright(1)   spin for 1 second\n#     stop(2)       stand still for 2 seconds\n#     Example:      elif bumper == 1:\n#                       backward(1)\n#     While a move is running, new move calls are ignored until it ends.\n#  🎮 حرکت‌های آسان (یک دستور = کل حرکت؛ بدون timer و state):\n#     backward(5) عقب · forward(2) جلو · turnleft(1) و turnright(1) چرخش\n#     stop(2) ایست. تا حرکتی تمام نشده، دستورِ تازه نادیده گرفته می‌شود.\n#\n#  MOVETIME  (hold MY wheels — variable style, countdown is automatic)\n#     Set the wheels yourself, then say how long to KEEP them:\n#        elif color == green:\n#            wheelleft = -25\n#            wheelright = -25\n#            movetime = seconds(10)   # keep reversing for exactly 10 s\n#     The minus-minus happens by itself - no \"if timer > 0\" block needed.\n#     movetime counts down in the panel; 0 means the hold is over.\n#  🕐 با movetime چرخ‌ها را خودت تنظیم می‌کنی و می‌گویی چقدر نگهشان\n#     دارد — شمارش خودکار است و به بلوک «if timer > 0» نیازی نیست.\n#\n#  ROOMS  (only on maps that have them, like the Rooms house)\n#     room == 0   the living area / hall     room == 1   the KITCHEN\n#     room == 2   BEDROOM 1                  room == 3   BEDROOM 2\n#     clean1 / clean2 / clean3   how much of that room wears MY\n#     colour, 0..100 percent - so I can tell a finished room from\n#     one still waiting:  if clean2 > 80: go somewhere else!\n#     A marker rug sits at every door: purple = bedroom 1,\n#     green = the kitchen, purple on the south side = bedroom 2.\n#  🚪 اتاق‌ها (فقط روی نقشه‌های اتاق‌دار): room شماره‌ی اتاق فعلی است؛\n#     clean1 تا clean3 درصد تمیزیِ هر اتاق به رنگ من — اتاق تمام‌شده را\n#     ول کن برو بعدی! دم هر در فرش نشانه هست: بنفش = اتاق‌خواب ۱،\n#     سبز = آشپزخانه، بنفشِ سمت جنوب = اتاق‌خواب ۲.\n#\n#  INFO\n#     x, y  position (cm)   heading  facing (0..360 deg)\n#     mytiles / rivaltiles  tiles owned      timeleft  seconds left\n#  ℹ️ اطلاعات: x و y جای من (سانتی‌متر) · heading جهت (۰ تا ۳۶۰ درجه)\n#     mytiles کاشی‌های من · rivaltiles مالِ حریف · timeleft ثانیه‌های مانده\n#\n#  POSITION (GPS)  -  the BOTTOM-LEFT corner is (0,0), x grows right, y grows UP\n#     On the standard map the far corner is (1000,1000), the centre (500,500).\n#        goto(500, 500)   drive there on the straight line, hands-free;\n#                         the robot turns, drives, and stops by itself\n#        atgoal == 1      the goto has arrived (0 while still driving)\n#        distto(x, y)     distance to a point in cm\n#        angleto(x, y)    compass direction to a point (compare with heading)\n#        stopgoto()       cancel the goto and take the wheels back\n#     goto does NOT dodge furniture, walls, the cat or the dog -\n#     watch bumper and the sensors while it drives!\n#     Example:   if timeleft < 20:\n#                    goto(500, 500)      # go camp the centre at the end\n#  📍 جی‌پی‌اس: گوشه‌ی پایین-چپ (0,0) است. goto(500,500) یعنی خودش تا\n#     آن نقطه براند و بایستد؛ atgoal که ۱ شد یعنی رسید. حواست باشد:\n#     goto از روی مبل و دیوار و گربه رد نمی‌شود — سپر و سنسورها را بپا!\n#\n#  BATTERY + CHARGING STATION  -  the U19 league only\n#     battery          0..100, how much charge is left\n#                      100% = about 60 s of full-throttle driving\n#     dockx, docky     where the charging station is, in cm (same grid as x,y)\n#                      a FIXED home by the east shelf - the same every match\n#                      both are -1 in FS and U14 (there is no station)\n#     Park ON the pad to refill: +25% per second. An EMPTY battery STOPS the\n#     robot dead where it stands - it will not move again, so leave enough\n#     charge to get back!   Rule of thumb: keep more than\n#         distto(dockx, docky) / 30   percent in the tank.\n#     Example:   if battery < 30:\n#                    goto(dockx, docky)  # go charge, then carry on\n#     The 10s \"stuck\" watchdog is paused while you are charging, but it\n#     comes back the moment you are full - do NOT camp on the pad.\n#  🔋 باتری و ایستگاه شارژ (فقط U19): باتری ۱۰۰٪ ≈ ۶۰ ثانیه راندن با\n#     تمام سرعت. روی پد پارک کن تا ۲۵٪ در ثانیه پر شود. باتریِ صفر یعنی\n#     ربات همان‌جا برای همیشه می‌ایستد — به‌اندازه‌ی راه برگشت شارژ نگه دار.\n#\n#  ASSISTIVE TECHNOLOGY league  -  you are GUIDING a person\n#     backleft, backright  the person walks BEHIND you - this is how you\n#                          notice when they stop or fall behind\n#     personback           distance to them in cm (60-70 = comfortable)\n#     personwait == 1      they lost you and stopped to wait\n#     goalx, goaly         where they want to go   (-1 in U19)\n#     goalname             WHICH room: compare with kitchen / door / sofa /\n#                          bedroom / window / table\n#     roomx(kitchen)       ask the house for a room's address (U19)\n#     goalsleft            destinations still to deliver\n#     Fast is NOT the goal: +30 arriving with them, +20 for a chore\n#     done alone, -6 if they hit furniture, -100 if they FALL, and\n#     violent swerves cost too.\n#  🦯 لیگ فناوری کمکی: تو راهنمای یک آدمی که پشت سرت راه می‌رود.\n#     personback فاصله‌اش تا توست (۶۰ تا ۷۰ خوب است) و سرعتِ زیاد\n#     اصلاً هدف نیست — اگر بیفتد ۱۰۰ امتیاز می‌روی عقب!\n#\n#  SUMO league  -  the knockout bout (that league ships its own program)\n#     arenax, arenay, arenar  the platform: centre and radius (cm)\n#     edge                    my distance to the drop, in cm\n#     rivalx, rivaly          where the rival is\n#     cliff1..cliffN == 1     that edge sensor sees the DROP\n#     Shove the rival off the platform - first to 3 knockouts wins.\n#  🤼 لیگ سومو: حریف را از سکو بینداز پایین — edge فاصله‌ات تا لبه است\n#     و cliff یعنی آن سنسورِ لبه، پرتگاه را می‌بیند.\n#\n#  WHEELS  (set these every step, from -25 to 25)\n#      25,  25  = forward, full speed      -25, -25 = backward\n#      25, -25  = turn right in place      -25,  25 = turn left in place\n#      12,  12  = forward at half speed\n#  🛞 چرخ‌ها (هر قدم مقدار بده؛ از -۲۵ تا ۲۵):\n#     «۲۵ و ۲۵» جلو با تمام سرعت · «-۲۵ و -۲۵» عقب\n#     «۲۵ و -۲۵» چرخش درجا به راست · «-۲۵ و ۲۵» به چپ · «۱۲ و ۱۲» نصف سرعت\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\n# Do NOT write your own code inside this block.\n# بازی این بلوک را کامل رد می‌کند! فقط برای این است که ویرایشگر کد\n# اسم سنسورها را بشناسد و زیرشان خط قرمز نکشد. کد خودت را اینجا ننویس.\nfront = 200; frontleft = 200; frontright = 200\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0; movetime = 0; atgoal = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nbattery = 100; dockx = -1; docky = -1\npersonback = 60; personwait = 0; goalx = -1; goaly = -1; goalname = 0; goalsleft = 0\nkitchen = 1; door = 2; sofa = 3; bedroom = 4; window = 5; table = 6\nzonex = -1; zoney = -1; zoner = -1; inzone = 0; rivalinzone = 0; rivalx = -1; rivaly = -1\nroom = 0; clean1 = 0; clean2 = 0; clean3 = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\n\n# ---------- HOW THIS WORKS ----------\n# This file runs 10 times every second, from top to bottom.\n# Your code cannot \"wait\", so a move that should last a while is started\n# by putting a number in `timer`, and `state` remembers WHICH move it is:\n#     state = 1  -> turning right      state = -1 -> turning left\n#     state = 2  -> reversing\n# Every step the first block counts the timer down and keeps that move going.\n#\n# 🧭 این‌جوری کار می‌کند: کدت نمی‌تواند «صبر» کند؛ حرکتی که باید طول\n# بکشد را با یک عدد در timer شروع می‌کنی و state یادش می‌ماند «کدام»\n# حرکت بود. بلوک اول در هر قدم تایمر را کم می‌کند و همان را ادامه می‌دهد.\n#\n# HOW LONG IS A TURN?  timer counts steps, 10 steps = 1 second:\n#     timer = 3   ->  0.3 s of turning  =  about  50 degrees\n#     timer = 5   ->  0.5 s of turning  =  about  80 degrees\n#     timer = 10  ->  1.0 s of turning  =  about 165 degrees\n# Want the robot to turn further? Just use a BIGGER number in timer.\n# 🔄 چقدر بچرخم؟ ۱۰ قدم = ۱ ثانیه: timer = 3 حدود ۵۰ درجه ·\n#    timer = 5 حدود ۸۰ درجه · timer = 10 حدود ۱۶۵ درجه.\n#\n# Add your own elif branches below - the first one that is true wins.\n# ✍️ شاخه‌های elif خودت را پایین اضافه کن — اولین شرطِ درست برنده است.\n\n\n# ---------- THE ROBOT LOGIC ----------\n\nwheelleft = 25                   # by default: drive straight ahead, full speed\nwheelright = 25                  # پیش‌فرض: مستقیم جلو با تمام سرعت\n\n# ۱) آیا هنوز مشغول حرکت قبلی‌ام؟ تا timer صفر نشده همان را ادامه بده.\nif timer > 0:                    # 1) am I still busy with the last move?\n    timer -= 1\n    if state == 2:               #    reversing in a curve (one wheel slower,\n        wheelleft = -25          #    so we also rotate away and do not drive\n        wheelright = -8          #    straight back into the same spot)\n                                 #    دنده‌عقبِ کج: یک چرخ کندتر، تا هم دور\n                                 #    شویم هم دوباره به همان‌جا برنگردیم\n    elif state == 1:             #    turning right · چرخش به راست\n        wheelleft = 18\n        wheelright = -18\n    else:                        #    turning left · چرخش به چپ\n        wheelleft = -18\n        wheelright = 18\n\n# ۲) به چیزی خوردم — ۰٫۴ ثانیه دنده‌عقب (شاید گربه باشد، شاید حریف!).\nelif bumper == 1:                # 2) I TOUCHED something -> reverse for 0.4 s\n    state = 2\n    timer = 4\n    wheelleft = -25\n    wheelright = -25\n\n# ۳) دیوار نزدیک‌تر از ۷۵ سانتی‌متر روبه‌روست — عقب بکش، بعد راست بچرخ.\n#    timer = 3 یعنی ۰٫۳ ثانیه چرخش (حدود ۵۰ درجه)؛ عدد بزرگ‌تر = چرخش بیشتر!\nelif front < 75:                 # 3) wall closer than 75 cm ahead\n    state = 1                    #    -> back off, then turn right\n    timer = 3                    #    timer = 3 -> turn 0.3 s (about 50 degrees)\n    wheelleft = -10              #       use a bigger number to turn further!\n    wheelright = -10\n\n# ۴) چیزی نزدیک‌تر از ۴۵ سانتی‌متر سمتِ چپِ جلوست — عقب بکش، راست بچرخ.\nelif frontleft < 45:             # 4) something closer than 45 cm on my LEFT\n    state = 1                    #    -> back off, then turn right\n    timer = 3\n    wheelleft = -10\n    wheelright = -10\n\n# ۵) چیزی سمتِ راستِ جلوست. 🧪 امتحان کن: state را -1 کن (چرخش به چپ)\n#    و ببین ربات چطور گیج می‌زند و گیر می‌کند — همیشه یک‌طرفه چرخیدن پایدارتر است!\nelif frontright < 45:            # 5) something closer than 45 cm on my RIGHT\n    state = 1                    #    TRY THIS: change to -1 (turn left) and watch\n    timer = 3                    #    the robot start to wobble and get stuck.\n    wheelleft = -10              #    Turning the same way every time is steadier!\n    wheelright = -10\n\n# 6) فرش‌ها: به‌صورت پیش‌فرض ربات از روی هر فرشی رد می‌شود و به رنگ کاری ندارد.\n#    اگر خواستی واکنش نشان بدهد، این چند خط را از کامنت دربیاور (مثلاً برای فرش بنفش):\n# elif color == purple:            # 6) the small PURPLE rug is right ahead\n#     state = 2                    #    -> reverse away from it for half a second\n#     timer = 5\n#     wheelleft = -25\n#     wheelright = -25\n\n# YOUR TURN: the big GREEN rug slows you down and gives no points,\n# but this code does nothing about it! Add your own elif here, e.g.:\n#     elif color == green:\n#         state = 2            # 2 = reverse (the timer block continues it!)\n#         timer = 10           # for 1 second\n#         wheelleft = -25\n#         wheelright = -25\n# Without state and timer the move stops the moment green disappears.\n# ✍️ نوبت توست: فرش سبزِ بزرگ سرعتت را نصف می‌کند و امتیازی هم ندارد،\n#    ولی این کد هیچ کاری برایش نمی‌کند! elif خودت را همین‌جا اضافه کن\n#    (نمونه‌اش بالاست). بدون state و timer، حرکت همان لحظه‌ای که سبز\n#    از جلوی سنسور برود قطع می‌شود.\n\nelse:                            # 7) nothing in the way -> full speed ahead\n    wheelleft = 25               #    راه باز است — با تمام سرعت تمیز کن!\n    wheelright = 25\n", "leagues/vacuum/u19/program.py": "# type: ignore\n# cspell:ignore frontleft frontright backleft backright wheelleft wheelright mytiles rivaltiles atgoal distto angleto stopgoto timeleft dockx docky\n# ============================================================\n#  BATTERY RUNNER  -  for the U19 league.\n#  🔋 دونده‌ی باتری‌دار — برنامه‌ی شروع رده‌ی U19.\n#\n#  In U19 the robot runs on a battery:\n#     battery        100 -> 0   (100% is about 60 s of full speed)\n#     dockx, docky   the charging station, in cm - it has a FIXED\n#                    home by the wall, the same in every match\n#  در U19 ربات با باتری کار می‌کند: battery از ۱۰۰ تا ۰ (۱۰۰٪ یعنی\n#  حدود ۶۰ ثانیه با تمام سرعت). dockx و docky جای ایستگاه شارژ است —\n#  جای ثابتی کنار دیوار، در همه‌ی مسابقه‌ها همان‌جا.\n#\n#  Park ON the pad and it refills at +25% per second.\n#  An EMPTY battery STOPS the robot dead, right where it\n#  stands, for the rest of the match - so the real skill\n#  is leaving for the dock in time, every time.\n#  روی پد پارک کن: ۲۵٪ در ثانیه پر می‌شود. باتریِ صفر یعنی ربات\n#  همان‌جا تا آخر مسابقه خاموش می‌ماند — مهارتِ واقعی این است که\n#  هر بار «به‌موقع» راهیِ ایستگاه شوی.\n#\n#  The 10 s \"stuck\" watchdog is paused while you charge, but it\n#  is back the moment you hit 100% - so do not camp on the pad.\n#  تا وقتی در حال شارژی، داورِ «گیرکردن» کاری به تو ندارد؛ ولی\n#  همین که پر شدی برمی‌گردد — روی پد چادر نزن!\n#\n#  HOW MUCH CHARGE DO I NEED TO GET HOME?\n#  At full speed the robot burns about 1.7% per second and covers\n#  about 60 cm in that second - but the RUG halves your speed and\n#  the trip is never a straight line, so budget generously:\n#         distto(dockx, docky) / 25   percent.\n#  Plus a FAT margin, because goto() drives a STRAIGHT line and\n#  the real trip never is: round the sofa, wait for the dog, back\n#  out of a corner. Dying at 0% is now FINAL - once the battery is\n#  empty the robot stands there for the rest of the match - so\n#  when in doubt, leave for the dock EARLY.\n#  ⛽ چقدر شارژ برای برگشتن لازم دارم؟ با تمام سرعت حدود ۱٫۷٪ در\n#  ثانیه می‌سوزد و ۶۰ سانتی‌متر می‌روی — ولی فرش سرعتت را نصف می‌کند\n#  و مسیر هیچ‌وقت خط راست نیست. پس دست‌ودل‌باز حساب کن:\n#  distto(dockx, docky) / 25 درصد + یک حاشیه‌ی چاق. شک داری؟ زودتر برو!\n#\n#  THE STATE MACHINE\n#     state 0   cleaning\n#     state 1   driving home\n#     state 2   sitting on the pad, drinking\n#     state 3   backing out of whatever we hit\n#     state 4   sidestepping ALONG it before trying again\n#  Writing it as states is what makes it reliable: whatever\n#  happens, the robot always knows what it was in the middle of.\n#  The escape side (flip) is read off the SENSORS at each bump -\n#  we back out toward whichever side is open. Bashing the same\n#  corner from the same angle over and over is how batteries die.\n#  ⚙️ ماشین حالت:\n#     state 0 تمیزکاری · state 1 در راه خانه · state 2 روی پد در حال\n#     شارژ · state 3 عقب‌کشیدن از چیزی که به آن خوردیم · state 4\n#     سُرخوردن در امتدادش پیش از تلاش دوباره.\n#  حالت‌نویسی همان چیزی است که برنامه را قابل‌اعتماد می‌کند: هرچه پیش\n#  بیاید، ربات می‌داند وسطِ چه کاری بود. سمتِ فرار (flip) هر بار از\n#  روی سنسورها خوانده می‌شود — به سمتِ بازتر عقب می‌کشیم. کوبیدن به\n#  همان کنج از همان زاویه، راهِ مردن باتری است.\n#\n#  THE DUST BIN  -  ONE-PLAYER matches only\n#     dust      how many tiles are in the bin, 0..30\n#     dustfull  1 = FULL, and a full robot cleans NOTHING\n#     dumpx, dumpy   the emptying station, in cm. It is its own\n#                    machine, NOT the charging pad - two errands.\n#  Drive within reach of it and the bin empties itself. Leave it\n#  too late and you spend the whole trip home cleaning nothing,\n#  so go when the bin is nearly full and the station is near.\n#  🗑 مخزن خاک (فقط مسابقه‌ی تک‌نفره): dust تعداد کاشی‌های داخل مخزن\n#  است (۰ تا ۳۰) و dustfull یعنی پُرِ پُر — رباتِ پُر «هیچ» چیزی تمیز\n#  نمی‌کند! ایستگاه تخلیه (dumpx و dumpy) دستگاهِ خودش است، نه پد شارژ:\n#  دو مأموریت، دو سفر. نزدیکش برسی خودش خالی می‌شود.\n#\n#  ROOMS  (only on maps that have them, like the Rooms house)\n#     room == 0  hall   1  KITCHEN   2  BEDROOM 1   3  BEDROOM 2\n#     clean1 / clean2 / clean3   how much of that room wears MY\n#     colour, 0..100 percent - a finished room is a room to leave.\n#  🚪 اتاق‌ها (فقط نقشه‌های اتاق‌دار): room شماره‌ی اتاق فعلی؛\n#     clean1 تا clean3 درصد تمیزیِ هر اتاق — اتاقِ تمام‌شده را ترک کن.\n# ============================================================\n\n# === EDITOR SETUP ==============================================\n# The game SKIPS this whole block! It exists only so VS Code knows\n# these names and stops drawing red lines under them.\n# بازی این بلوک را کامل رد می‌کند! فقط برای این است که ویرایشگر کد\n# اسم سنسورها را بشناسد و زیرشان خط قرمز نکشد. کد خودت را اینجا ننویس.\nfront = 200; frontleft = 200; frontright = 200\nleft = 200; right = 200; backleft = 200; backright = 200\ncolor = 0; bumper = 0; timer = 0; state = 0; movetime = 0; atgoal = 0\nwhite = 0; red = 1; blue = 2; green = 3; black = 4; purple = 5\nx = 0; y = 0; heading = 0; mytiles = 0; rivaltiles = 0; timeleft = 0\nbattery = 100; dockx = -1; docky = -1\ndust = 0; dustmax = 0; dustfull = 0; dumpx = -1; dumpy = -1\nhome = 0; needed = 0; flip = 0\nroom = 0; clean1 = 0; clean2 = 0; clean3 = 0\nwheelleft = 0; wheelright = 0\n# === END EDITOR SETUP ==========================================\n\n\n# ---------- how far is home, and how low is too low? ----------\n# خانه چقدر دور است، و چند درصد یعنی «خیلی کم»؟\nhome = distto(dockx, docky)\nneeded = home / 25 + 25\n\n\n# ---------- state 3: back out of whatever we hit ----------\n# حالت ۳: از چیزی که به آن خوردیم عقب بکش — به سمتی که موقع برخورد بازتر بود.\nif state == 3:\n    if timer > 0:\n        timer -= 1\n        if flip < 1:             # the side picked at the moment of the bump\n            wheelleft = -22      # سمتی که لحظه‌ی برخورد انتخاب شد\n            wheelright = -8\n        else:\n            wheelleft = -8\n            wheelright = -22\n    else:\n        state = 4                # clear of it -> now slide ALONG it\n        timer = 12               # جدا شدیم — حالا در امتدادش سُر بخور\n\n\n# ---------- state 4: sidestep along the obstacle, then retry ----------\n# حالت ۴: در امتداد مانع جابه‌جا شو، بعد دوباره راه خانه را امتحان کن.\nelif state == 4:\n    if bumper == 1:              # hit something ELSE mid-sidestep? back out\n        if frontleft > frontright:   # وسط راه به چیز دیگری خوردیم؟ باز هم\n            flip = 0             # again toward whichever side is open NOW\n        else:                    # به سمتِ بازتر عقب بکش\n            flip = 1\n        state = 3\n        timer = 10\n        wheelleft = -20\n        wheelright = -8\n    elif timer > 0:\n        timer -= 1\n        if flip < 1:\n            wheelleft = 8        # a forward arc across the obstacle's face,\n            wheelright = 24      # not into it\n                                 # قوسی رو به جلو از کنار مانع — نه توی آن\n        else:\n            wheelleft = 24\n            wheelright = 8\n    else:\n        state = 1                # try the trip home again from HERE\n        timer = 200              # fresh 20-second deadline\n        goto(dockx, docky)       # از همین‌جا دوباره راه خانه را برو —\n                                 # با مهلت تازه‌ی ۲۰ ثانیه‌ای\n\n\n# ---------- state 2: on the pad, drinking ----------\n# حالت ۲: روی پد نشسته‌ایم و شارژ می‌نوشیم — از روی پد قِل نخور!\nelif state == 2:\n    wheelleft = 0                # do NOT roll off the pad\n    wheelright = 0\n    if battery > 95:\n        state = 0                # full -> back to work · پر شد؟ برگرد سر کار\n\n\n# ---------- state 1: driving home ----------\n# حالت ۱: در راه خانه — goto فرمان را دارد؛ ما فقط مواظب برخورد و کهنه‌شدن سفریم.\nelif state == 1:\n    timer -= 1\n    if bumper == 1 or timer <= 0:\n        # hit something - or the trip went STALE (20 s without arriving).\n        # Either way: stop, back out toward the open side, try fresh.\n        # به چیزی خوردیم — یا سفر بیات شد (۲۰ ثانیه بی‌نتیجه). در هر دو\n        # حالت: بایست، به سمتِ باز عقب بکش، از نو امتحان کن.\n        stopgoto()\n        if frontleft > frontright:\n            flip = 0             # more room to the LEFT -> escape that way\n        else:                    # سمت چپ بازتر است — از همان‌جا فرار کن\n            flip = 1             # more room to the RIGHT · سمت راست بازتر\n        state = 3\n        timer = 10\n        wheelleft = -20\n        wheelright = -8\n    elif home < 25:              # close enough: stop and let it charge\n        stopgoto()               # به‌اندازه‌ی کافی نزدیکیم: بایست تا شارژ شود\n        state = 2\n        wheelleft = 0\n        wheelright = 0\n    # else: goto is steering, leave the wheels alone\n    # در غیر این صورت goto دارد می‌راند — به چرخ‌ها دست نزن\n\n\n# ---------- state 0: cleaning ----------\n# حالت ۰: تمیزکاری — و همیشه یک چشم به باتری.\nelse:\n    # time to head home? Two triggers: the sensible one, and the emergency one.\n    # وقتِ برگشتن است؟ دو ماشه دارد: حسابگرانه (شارژ به‌اندازه‌ی مسیر +\n    # حاشیه) و اضطراری (زیر ۲۰٪ — دیگر بحث نکن، فقط برو!).\n    if dockx > 0 and battery < needed:\n        state = 1\n        timer = 200              # a trip gets 20 seconds, then we rethink -\n        goto(dockx, docky)       # long enough to cross the slow rug honestly\n                                 # هر سفر ۲۰ ثانیه مهلت دارد، بعد بازنگری —\n                                 # آن‌قدر که از روی فرشِ کند هم صادقانه رد شویم\n    elif dockx > 0 and battery < 20:\n        state = 1\n        timer = 200\n        goto(dockx, docky)\n\n    elif front < 25 or bumper == 1:      # something right ahead -> turn away\n        wheelleft = 25                   # چیزی درست جلوست — رویت را برگردان\n        wheelright = -25\n    elif frontleft < frontright:         # more room on the right\n        wheelleft = 25                   # سمت راست بازتر است — قوس به راست\n        wheelright = 12\n    elif frontright < frontleft:         # more room on the left\n        wheelleft = 12                   # سمت چپ بازتر است — قوس به چپ\n        wheelright = 25\n    else:\n        wheelleft = 25                   # clear -> full speed, clean!\n        wheelright = 25                  # راه باز است — با تمام سرعت تمیز کن!\n"});
